window.NPC_CHUNK_126 = [{"name":"Skeletal Guardian Tier 4-5","cr":5,"xp":1600,"race":"Young copper dragon","age_category":"young","alignment":"NE","size":"Medium","type":"undead","sub_types":["earth"],"templates_applied":"@skeleton","init":7,"senses":["darkvision 60 ft."],"ac":25,"ac_touch":13,"ac_flat_footed":22,"ac_mods":"+3 Dex, +12 natural","hp":45,"hd":"10d8","hd_value":10,"fort":3,"ref":6,"will":7,"dr":"5/bludgeoning","immunities":["undead traits"],"speed":[{"type":"land","speed":40}],"melee":"bite +11 (1d8+4), 2 claws +11 (1d4+4), 2 wings +6 (1d4+2)","space":"5 ft.","reach":"5 ft.","strength":19,"dexterity":16,"wisdom":10,"charisma":10,"baseatk":7,"cmb":11,"cmd":24,"feats":[{"feat":"Improved Initiative","type":"bonus"}],"before_combat":"The skeletal guardian remains still as the PCs explore the room, waiting until the first PC steps into the hallway.","during_combat":"The skeleton attacks the nearest target and only changes its target when its current victim is dead or unconscious. As an unintelligent undead, it employs no strategies in combat, and moves as needed to attack, even if doing so restricts it to a single attack per round.","morale":"Unintelligent and created for a singular purpose, the skeletal guardian fights until destroyed, but doesn't leave area 1 if the PCs flee.","source":"PFS S2-11, Pathfinder RPG Bestiary 106, 250"},{"name":"Mazzel Gol","cr":3,"xp":800,"race":"fetchling","gender":"Female","age_category":"Adult","classes":[{"class":"alchemist","level":4}],"alignment":"CE","size":"Medium","type":"outsider","sub_types":["native"],"init":7,"senses":["darkvision 60 ft.","low-light vision"],"ac":18,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+3 armor, +3 Dex, +2 natural","hp":27,"hd":"4d8+6","hd_value":4,"fort":6,"ref":8,"will":1,"save_mods":"+2 vs. poison","resists":["cold 5","electricity 5"],"speed":[{"type":"land","speed":30}],"melee":"bite +6 (1d8+3), 2 claws +6 (1d6+3)","ranged":"bomb +7 (2d6+2 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bomb","details":"8/day, 2d6+2 fire, DC 14"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"disguise self","details":"humanoid only"}]}],"extractsprepared_caster":"alchemist","extractsprepared_caster_level":4,"extractsprepared":[{"spell_level":2,"spells":[{"spell":"invisibility"},{"spell":"spider climb"}]},{"spell_level":1,"spells":[{"spell":"comprehend languages"},{"spell":"cure light wounds"},{"spell":"identify"},{"spell":"true strike"}]}],"strength":16,"dexterity":16,"constitution":13,"intelligence":14,"wisdom":8,"charisma":10,"baseatk":3,"cmb":6,"cmd":19,"feats":[{"feat":"Brew Potion"},{"feat":"Extra Bombs*"},{"feat":"Improved Initiative"},{"feat":"Throw Anything"}],"skills":[{"skill":"Appraise","value":9},{"skill":"Craft (alchemy)","value":9},{"skill":"Disable Device","value":10},{"skill":"Heal","value":6},{"skill":"Knowledge (arcana)","value":9},{"skill":"Knowledge (planes)","value":5},{"skill":"Perception","value":6},{"skill":"Spellcraft","value":9},{"skill":"Stealth","value":6}],"languages":["Common","Aklo","D'ziriak (cannot speak)","Draconic"],"sq":["alchemy (alchemy crafting +4, identify potions)","discoveries (acid bomb, feral mutagen)","mutagen (+4 Str/-2 Int, +2 natural armor, 40 minutes)","poison use","swift alchemy"],"special_abilities":[{"type":"Shadow Blending","kind":"Su","details":"Attacks against a fetchling in dim light have a 50% miss chance instead of the normal 20% miss chance. This ability doesn't grant total concealment; it just increases the miss chance."}],"gear":"masterwork studded leather, dagger, cloak of resistance +1, alchemist's lab, 38 gp, potions of cure light wounds (2), alchemical grease* (2), weapon blanch (adamantine)","before_combat":"If Mazzel Gol hears the sounds of combat in the next room, she immediately drinks her mutagen (already included in her stats). If time further permits, she drinks her extracts of spider climb and invisibility, and readies her true strike extract.","during_combat":"Mazzel Gol initiates combat by throwing an acid bomb into the largest group of PCs she can target. She fights recklessly with her claws and bite, climbing up the walls if she's cornered or facing an opponent she can neither hit nor effectively damage, and then resorting to bombs from range.","morale":"While under the effect of her extract, Mazzel Gol is maniacal and fights to the death.","base_statistics":"When not under the effect of her mutagen, Mazzel Gol has the following stats: AC 16, flat 13; Melee dagger +4 (1d4+1/19-20); Ranged bomb +7 (2d6+3 fire); Skills Appraise +10, Craft (alchemy) +10, Knowledge (arcana) +10, Knowledge (planes) +6, Spellcraft +10","source":"PFS S2-11, Pathfinder RPG Advanced Player's Guide 26, Pathfinder RPG Bestiary 2 123"},{"name":"Mazzel Gol Tier 4-5","cr":6,"xp":2400,"race":"fetchling","gender":"Female","age_category":"Adult","classes":[{"class":"alchemist","level":7}],"alignment":"CE","size":"Medium","type":"outsider","sub_types":["native"],"init":7,"senses":["darkvision 60 ft.","low-light vision"],"ac":19,"ac_touch":14,"ac_flat_footed":16,"ac_mods":"+3 armor, +1 deflection, +3 Dex, +2 natural","hp":68,"hd":"7d8+33","hd_value":7,"fort":9,"ref":9,"will":2,"save_mods":"+4 vs. poison","resists":["cold 5","electricity 5"],"speed":[{"type":"land","speed":30}],"melee":"bite +8 (1d8+3), 2 claws +8 (1d6+3)","ranged":"bomb +9 (4d6+2 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bomb","details":"11/day, 4d6+2 fire, DC 15"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"disguise self","details":"humanoid only"}]}],"extractsprepared_caster":"alchemist","extractsprepared_caster_level":7,"extractsprepared":[{"spell_level":3,"spells":[{"spell":"haste"}]},{"spell_level":2,"spells":[{"spell":"cat's grace"},{"spell":"false life"},{"spell":"invisibility"},{"spell":"spider climb"}]},{"spell_level":1,"spells":[{"spell":"comprehend languages"},{"spell":"cure light wounds"},{"spell":"identify"},{"spell":"true strike"}]}],"strength":16,"dexterity":16,"constitution":17,"intelligence":14,"wisdom":8,"charisma":10,"baseatk":5,"cmb":8,"cmd":22,"feats":[{"feat":"Brew Potion"},{"feat":"Combat Reflexes"},{"feat":"Extra Bombs"},{"feat":"Improved Initiative"},{"feat":"Throw Anything"},{"feat":"Toughness"}],"skills":[{"skill":"Appraise","value":12},{"skill":"Craft (alchemy)","value":12},{"skill":"Disable Device","value":13},{"skill":"Heal","value":9},{"skill":"Knowledge (arcana)","value":12},{"skill":"Knowledge (planes)","value":5},{"skill":"Perception","value":9},{"skill":"Spellcraft","value":12},{"skill":"Stealth","value":6}],"languages":["Common","Aklo","D'ziriak (cannot speak)","Draconic"],"sq":["alchemy (alchemy crafting +7, identify potions)","discoveries (acid bomb, extend potion 2/day, feral mutagen)","mutagen (+4 Str/-2 Int, +2 natural armor, 70 minutes)","poison use","swift alchemy","swift poisoning"],"special_abilities":[{"type":"Shadow Blending","kind":"Su","details":"Attacks against a fetchling in dim light have a 50% miss chance instead of the normal 20% miss chance. This ability doesn't grant total concealment; it just increases the miss chance."}],"gear":"masterwork studded leather, masterwork dagger, cloak of resistance +1, ring of protection +1, alchemist's lab, 238 gp, potion of bear's endurance, potion of cure moderate wounds, alchemical grease* (2), weapon blanch (adamantine)","before_combat":"If Mazzel Gol hears the sounds of combat in the next room, she immediately drinks her mutagen and her bear's endurance potion, employing one of her daily uses of her extend potion discovery (already included in her stats). If time further permits, she drinks her extracts of spider climb and invisibility, and readies her haste extract.","during_combat":"Mazzel Gol initiates combat by throwing an acid bomb into the largest group of PCs she can target. She fights recklessly with her claws and bite, climbing up the walls if she's cornered or facing an opponent she can neither hit nor effectively damage, and then resorting to bombs from range.","morale":"If reduced below 25 hit points, the fetchling flees up the wall and drinks her false life extract, then resumes combat. While under the effect of her extract, Mazzel Gol is maniacal and fights to the death.","base_statistics":"Without any buffs, Mazzel Gol has the following stats: AC 17, flat-footed 14; Melee mwk dagger +7 (1d4+1/19-20); Ranged bomb +9 (2d6+3 fire); Skills Appraise +13, Craft (alchemy) +13, Knowledge (arcana) +13, Knowledge (planes) +6, Spellcraft +13","source":"PFS S2-11, Pathfinder RPG Advanced Player's Guide 26, Pathfinder RPG Bestiary 2 123"},{"name":"Shadow Guard","cr":0.3333,"xp":135,"race":"fetchling","gender":"Male and Female","age_category":"Adult","classes":[{"class":"warrior","level":1}],"alignment":"NE","size":"Medium","type":"outsider","init":1,"senses":["darkvision 60 ft.","low-light vision"],"ac":14,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+3 armor, +1 Dex","hp":8,"hd":"1d10+3","hd_value":1,"fort":2,"ref":1,"will":0,"resists":["cold 5","electricity 5"],"speed":[{"type":"land","speed":30}],"melee":"longsword +2 (1d8+1/19-20)","ranged":"sling +2 (1d4+1)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":1,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"disguise self","details":"humanoid only"}]}],"strength":13,"dexterity":12,"constitution":11,"intelligence":9,"wisdom":10,"charisma":10,"baseatk":1,"cmb":2,"cmd":13,"feats":[{"feat":"Toughness"}],"skills":[{"skill":"Intimidate","value":4},{"skill":"Knowledge (planes)","value":1},{"skill":"Profession (guard)","value":4},{"skill":"Stealth","value":3}],"languages":["Common"],"special_abilities":[{"type":"Shadow Blending","kind":"Su","details":"Attacks against a fetchling in dim light have a 50% miss chance instead of the normal 20% miss chance. This ability doesn't grant total concealment; it just increases the miss chance."}],"gear":"masterwork black studded leather, longsword, sling with 10 bullets, manacles, 15 gp, alchemist's fire (2)","before_combat":"If the guards are aware of the PCs' presence, they spread out throughout the room preparing to ambush the PCs as these intruders enter the laboratory.","during_combat":"The guards charge the nearest PC at the onset of the combat, attempting to drive the intruders out of the room and away from the slaves in area 5.","morale":"While anything but good and certainly not cowardly, the guards are merely hired mercenaries of the Onyx Alliance and surrender if brought below 3 hit points.","source":"PFS S2-11, Pathfinder RPG Bestiary 2 123"},{"name":"Shadow Guard Tier 4-5","cr":1,"xp":400,"race":"fetchling","gender":"Male and Female","age_category":"Adult","classes":[{"class":"fighter","level":1},{"class":"rogue","level":1}],"alignment":"N","size":"Medium","type":"outsider","init":2,"senses":["darkvision 60 ft.","low-light vision"],"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+3 armor, +2 Dex, +1 shield","hp":20,"hd":"1d10+1d8+6","hd_value":2,"fort":3,"ref":4,"will":1,"resists":["cold 5","electricity 5"],"speed":[{"type":"land","speed":30}],"melee":"mwk longsword +4 (1d8+2/19-20)","ranged":"sling +3 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"spell_like_abilities_caster_level":2,"spell_like_abilities_concentration":2,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"disguise self","details":"humanoid only"}]}],"strength":15,"dexterity":14,"constitution":13,"intelligence":10,"wisdom":12,"charisma":10,"baseatk":1,"cmb":3,"cmd":15,"feats":[{"feat":"Combat Reflexes"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":7},{"skill":"Intimidate","value":5},{"skill":"Knowledge (planes)","value":2},{"skill":"Perception","value":6},{"skill":"Profession (guard)","value":6},{"skill":"Stealth","value":9}],"languages":["Common"],"sq":["trapfinding +1"],"special_abilities":[{"type":"Shadow Blending","kind":"Su","details":"Attacks against a fetchling in dim light have a 50% miss chance instead of the normal 20% miss chance. This ability doesn't grant total concealment; it just increases the miss chance."}],"gear":"masterwork studded leather, masterwork light wooden shield, masterwork longsword, sling with 10 bullets, manacles, 42 gp, alchemist's fire (2), liquid ice","before_combat":"If the guards are aware of the PCs' presence, they spread out throughout the room preparing to ambush the PCs as these intruders enter the laboratory.","during_combat":"The guards charge the nearest PC at the onset of the combat, attempting to drive the intruders out of the room and away from the slaves in area 5.","morale":"While anything but good and certainly not cowardly, the guards are merely hired mercenaries of the Onyx Alliance and surrender if brought below 7 hit points.","source":"PFS S2-11, Pathfinder RPG Bestiary 2 123"},{"name":"Shadow Hound","cr":2,"xp":600,"race":"Reduced HD shadow mastiff","age_category":"Adult","alignment":"NE","size":"Small","type":"outsider","sub_types":["evil"],"init":7,"senses":["darkvision 60 ft."],"ac":16,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+3 Dex, +2 natural, +1 size","hp":25,"hd":"3d10+9","hd_value":3,"fort":6,"ref":6,"will":2,"defensive_abilities":["shadow blend"],"speed":[{"type":"land","speed":50}],"melee":"bite +6 (1d4+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bay"}],"strength":15,"dexterity":17,"constitution":16,"intelligence":4,"wisdom":12,"charisma":13,"baseatk":3,"cmb":4,"cmd":17,"feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":7},{"skill":"Stealth","value":13},{"skill":"Survival","value":7}],"languages":["Common (cannot speak)"],"special_abilities":[{"type":"Bay","kind":"Su","details":"When a shadow mastiff howls or barks, all creatures except evil outsiders within a 300-foot spread must succeed on a DC 13 Will save or become panicked for 1d4 rounds. This is a sonic, mind-affecting fear effect. A creature that successfully saves cannot be affected by the same mastiff's bay for 24 hours. The save DC is Charisma-based and includes a +1 racial bonus."},{"type":"Shadow Blend","kind":"Su","details":"In any condition of illumination other than full daylight, a shadow mastiff disappears into the shadows, giving it concealment. Artificial illumination, even a light or continual flame spell, doesn't negate this ability. A daylight spell, however, does. A shadow mastiff can suspend or resume this ability as a free action."}],"before_combat":"The shadow hound lurks behind one of the room's larger crates, waiting to be fed. When the PCs enter, it doesn't recognize their scent and initiates combat with its bay ability.","during_combat":"Frenzied, the hound deactivates its shadow blend ability as it attacks the PCs. The hound pursues the intruders to the length of its chain. If reduced below 10 hp, it activates its shadow blend and continues fighting while remaining in whatever shadows it can find among the room's clutter.","morale":"The shadow hound fights to the death, and howls loudly and relentlessly if the PCs move beyond its reach.","source":"PFS S2-11, Pathfinder RPG Bonus Bestiary 16"},{"name":"Shadow Hound Tier 4-5","cr":5,"xp":1600,"race":"Shadow mastiff","age_category":"Adult","alignment":"NE","size":"Medium","type":"outsider","sub_types":["evil"],"init":6,"senses":["darkvision 60 ft.","scent"],"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+2 Dex, +5 natural","hp":51,"hd":"6d10+18","hd_value":6,"fort":8,"ref":7,"will":5,"defensive_abilities":["shadow blend"],"speed":[{"type":"land","speed":50}],"melee":"bite +10 (1d6+6 plus trip)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bay"}],"strength":19,"dexterity":15,"constitution":17,"intelligence":4,"wisdom":12,"charisma":13,"baseatk":6,"cmb":10,"cmd":22,"feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":10},{"skill":"Stealth","value":11},{"skill":"Survival","value":10}],"languages":["Common (cannot speak)"],"special_abilities":[{"type":"Bay","kind":"Su","details":"When a shadow mastiff howls or barks, all creatures except evil outsiders within a 300-foot spread must succeed on a DC 16 Will save or become panicked for 2d4 rounds. This is a sonic, mind-affecting fear effect. A creature that successfully saves cannot be affected by the same mastiff's bay for 24 hours. The save DC is Charisma-based and includes a +2 racial bonus."},{"type":"Shadow Blend","kind":"Su","details":"In any condition of illumination other than full daylight, a shadow mastiff disappears into the shadows, giving it total concealment. Artificial illumination, even a light or continual flame spell, doesn't negate this ability. A daylight spell, however, does. A shadow mastiff can suspend or resume this ability as a free action."}],"before_combat":"The shadow hound lurks behind one of the room's larger crates, waiting to be fed. When the PCs enter, it doesn't recognize their scent and initiates combat with its bay ability.","during_combat":"The hound pursues PCs to the length of its chain, attacking while trying to remain at least partially hidden in the shadows of the crates and cargo stored here in the Material Plane.","morale":"The shadow hound fights to the death, and howls loudly and relentlessly if the PCs move beyond its reach.","source":"PFS S2-11, Pathfinder RPG Bonus Bestiary 16"},{"name":"Uthil Mak","cr":3,"xp":800,"race":"fetchling","gender":"Male","age_category":"Adult","classes":[{"class":"monk","level":4}],"alignment":"LE","size":"Medium","type":"outsider","sub_types":["native"],"init":2,"senses":["darkvision 60 ft.","low-light vision"],"ac":17,"ac_touch":16,"ac_flat_footed":14,"ac_mods":"+1 armor, +2 Dex, +1 dodge, +1 monk, +2 Wis","hp":35,"hd":"4d8+12","hd_value":4,"fort":6,"ref":7,"will":7,"save_mods":"+2 vs. enchantment","defensive_abilities":["evasion"],"speed":[{"type":"land","speed":40}],"melee":"unarmed strike +6 (1d8+2) or flurry of blows +4 (1d8+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"flurry of blows"},{"type":"stunning fist","details":"4/day, DC 14"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"disguise self","details":"humanoid only"}]}],"strength":14,"dexterity":15,"constitution":12,"intelligence":10,"wisdom":14,"charisma":10,"baseatk":3,"cmb":6,"cmd":21,"feats":[{"feat":"Combat Reflexes"},{"feat":"Deflect Arrows"},{"feat":"Dodge"},{"feat":"Improved Unarmed Strike"},{"feat":"Stunning Fist"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Knowledge (arcana)","value":3},{"skill":"Knowledge (planes)","value":3},{"skill":"Knowledge (religion)","value":7},{"skill":"Stealth","value":12}],"languages":["Common"],"sq":["fast movement","ki pool (4 points, magic)","maneuver training","slow fall 20 ft.","still mind"],"special_abilities":[{"type":"Shadow Blending","kind":"Su","details":"Attacks against a fetchling in dim light have a 50% miss chance instead of the normal 20% miss chance. This ability doesn't grant total concealment; it just increases the miss chance."}],"gear":"ceremonial dagger, bracers of armor +1, cloak of resistance +1, potion of cure moderate wounds, potion of shield of faith","before_combat":"Uthil Mak is engaged fully in his ritual and doesn'thing to prepare for the PCs' arrival. If they are exceptionally loud or he is otherwise alerted to their presence, he drinks his potion of shield of faith before continuing the rite.","during_combat":"The fetchling backs against a wall or the Wightir Conjunction to avoid being flanked and fights any comers. He uses flurry of blows as often as possible, spending ki to add an extra attack when possible. If he takes more than 15 points of damage, he spends ki to increase his AC instead.","morale":"Uthil Mak fights to the death.","source":"PFS S2-11, Pathfinder RPG Bestiary 2 123"},{"name":"Uthil Mak Tier 4-5","cr":6,"xp":2400,"race":"fetchling","gender":"Male","age_category":"Adult","classes":[{"class":"monk","level":7}],"alignment":"LE","size":"Medium","type":"outsider","sub_types":["native"],"init":2,"senses":["darkvision 60 ft.","low-light vision"],"ac":17,"ac_touch":16,"ac_flat_footed":14,"ac_mods":"+1 armor, +2 Dex, +1 dodge, +1 monk, +2 Wis","hp":59,"hd":"7d8+21","hd_value":7,"fort":7,"ref":8,"will":8,"save_mods":"+2 vs. enchantment","defensive_abilities":["evasion"],"immunities":["disease"],"speed":[{"type":"land","speed":50}],"melee":"unarmed strike +9 (1d8+3) or flurry of blows +9 (1d8+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"flurry of blows"},{"type":"stunning fist","details":"7/day, DC 15"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"disguise self","details":"humanoid only"}]}],"strength":16,"dexterity":15,"constitution":12,"intelligence":10,"wisdom":14,"charisma":10,"baseatk":5,"cmb":10,"cmd":24,"feats":[{"feat":"Combat Reflexes"},{"feat":"Deflect Arrows"},{"feat":"Dodge"},{"feat":"Extra Ki"},{"feat":"Improved Unarmed Strike"},{"feat":"Mobility"},{"feat":"Stunning Fist"},{"feat":"Toughness"},{"feat":"Weapon Focus (unarmed strike)"}],"skills":[{"skill":"Acrobatics","value":13,"special":"+7 jump"},{"skill":"Knowledge (arcana)","value":3},{"skill":"Knowledge (planes)","value":6},{"skill":"Knowledge (religion)","value":10},{"skill":"Stealth","value":15}],"languages":["Common"],"sq":["fast movement","high jump","ki pool (7 points, magic)","maneuver training","purity of body","slow fall 30 ft.","still mind","wholeness of body"],"special_abilities":[{"type":"Shadow Blending","kind":"Su","details":"Attacks against a fetchling in dim light have a 50% miss chance instead of the normal 20% miss chance. This ability doesn't grant total concealment; it just increases the miss chance."}],"gear":"ceremonial dagger, belt of giant strength +2, bracers of armor +1, cloak of resistance +1, potion of barkskin, potion of cure serious wounds","before_combat":"Uthil Mak knows that he has limited time to complete the ritual on all his new slaves and focuses on the task at hand. If he is alerted to the PCs' presence, such as by the shadow hound's bay, he drinks his potion of barkskin, and continues the rite.","during_combat":"The fetchling backs against a wall or the Wightir Conjunction to avoid being flanked and fights any comers. He uses flurry of blows as often as possible, spending ki to add an extra attack when possible. If he takes more than 25 points of damage, he spends ki to increase his AC instead. If reduced to fewer than 20 hit points, he counts on Mobility and his fast movement to get him away from threats and buy him a chance to use his wholeness of body ability and his potion of cure serious wounds.","morale":"Uthil Mak fights to the death.","source":"PFS S2-11, Pathfinder RPG Bestiary 2 123"},{"name":"Tarnspawn","cr":6,"xp":2400,"race":"eel","age_category":"Adult","alignment":"NE","size":"Large","type":"monstrous humanoid","sub_types":["aquatic","augmented animal"],"templates_applied":"manimal","init":6,"senses":["darkvision 60 ft.","low-light vision","scent"],"ac":19,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+2 Dex, +8 natural, -1 size","hp":68,"hd":"8d10+24","hd_value":8,"fort":5,"ref":8,"will":9,"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":10},{"type":"swim","speed":30}],"melee":"bite +13 (1d8+6), 2 claws +14 (1d6+6)","ranged":"bile +9 (1d8/x3 acid)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"soul feast"},{"type":"spit bile"}],"strength":22,"dexterity":14,"constitution":16,"intelligence":9,"wisdom":12,"charisma":12,"baseatk":8,"cmb":15,"cmd":27,"feats":[{"feat":"Dazzling Display"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Intimidate","value":12},{"skill":"Perception","value":9},{"skill":"Stealth","value":7},{"skill":"Survival","value":9},{"skill":"Swim","value":14}],"languages":["Infernal (cannot speak)"],"sq":["amphibious","animal blood"],"special_abilities":[{"type":"Animal Blood","kind":"Ex","details":"A tarnspawn counts as both an animal and a monstrous humanoid for the purposes of spells, abilities, and effects that affect animals. A tarnspawn is allowed a Will save to resist spells and effects that specifically affect animals, even if the effect doesn't normally allow a Will save."},{"type":"Soul Feast","kind":"Su","details":"As a standard action, a tarnspawn may attempt to drink the soul from any adjacent humanoid creature killed within the last round, storing the life force inside itself to carry back to the Silver Tarn entity. Draining a soul is a touch attack that provokes an attack of opportunity. A tarnspawn may only store a single soul, and cannot use this ability if it has already feasted on a soul. A creature whose soul has been imbibed may not be returned from the dead with any magic short of a limited miracle. Slaying the tarnspawn releases the stored soul, allowing the character to be raised normally. If the tarnspawn returns to the Silver Tarn, both it and the soul are absorbed by the entity, permanently slaying both."},{"type":"Spit Bile","kind":"Ex","details":"Tarnspawn may spit a stream of acidic bile up to 40 ft. as a ranged attack."}],"before_combat":"If stalking humans or expecting combat, roughly half of a tarnspawn pack hides, attempting to prowl behind their prey or leap unexpectedly from ambush.","during_combat":"Tarnspawn in a group reserve one member each round to unleash a terrifying howl (using their Dazzling Display feat; remember to include a +4 bonus if the tarnspawn are larger than their opponents). They eschew weapons, instead using their claws and fangs and focusing on shaken opponents.","morale":"Tarnspawn fight until destroyed.","source":"PFS S2-12, Advanced Bestiary 167, Pathfinder RPG Bestiary 119"},{"name":"Tarnspawn Tier 10-11","cr":9,"xp":6400,"race":"giant moray eel","age_category":"Adult","classes":[{"class":"barbarian","level":3,"archetype":"savage barbarian"}],"alignment":"NE","size":"Large","type":"monstrous humanoid","sub_types":["aquatic","augmented animal"],"templates_applied":"manimal","init":6,"senses":["darkvision 60 ft.","low-light vision","scent"],"ac":18,"ac_touch":10,"ac_flat_footed":15,"ac_mods":"+2 Dex, +1 dodge, +8 natural, -2 rage, -1 size","hp":121,"hd":"8d10+3d12+58","hd_value":11,"fort":10,"ref":9,"will":12,"save_mods":"+1 vs. fear","defensive_abilities":["naked courage","uncanny dodge"],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":30}],"melee":"bite +18 (1d8+8/19-20), 2 claws +19 (1d6+8)","ranged":"bile +12 (1d8/x3 acid)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rage","details":"11 rounds/day"},{"type":"rage powers","details":"guarded stance [+1 dodge vs. melee]"},{"type":"soul feast"},{"type":"spit bile"}],"strength":26,"dexterity":14,"constitution":20,"intelligence":9,"wisdom":12,"charisma":12,"baseatk":11,"cmb":20,"cmd":30,"feats":[{"feat":"Dazzling Display"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Intimidate","value":23},{"skill":"Perception","value":10},{"skill":"Stealth","value":8},{"skill":"Survival","value":13},{"skill":"Swim","value":16}],"languages":["Infernal (cannot speak)"],"sq":["amphibious","animal blood","fast movement"],"special_abilities":[{"type":"Animal Blood","kind":"Ex","details":"A tarnspawn counts as both an animal and a monstrous humanoid for the purposes of spells, abilities, and effects that affect animals. A tarnspawn is allowed a Will save to resist spells and effects that specifically affect animals, even if the effect doesn't normally allow a Will save."},{"type":"Soul Feast","kind":"Su","details":"As a standard action, a tarnspawn may attempt to drink the soul from any adjacent humanoid creature killed within the last round, storing the life force inside itself to carry back to the Silver Tarn entity. Draining a soul is a touch attack that provokes an attack of opportunity. A tarnspawn may only store a single soul, and cannot use this ability if it has already feasted on a soul. A creature whose soul has been imbibed may not be returned from the dead with any magic short of a limited miracle. Slaying the tarnspawn releases the stored soul, allowing the character to be raised normally. If the tarnspawn returns to the Silver Tarn, both it and the soul are absorbed by the entity, permanently slaying both."},{"type":"Spit Bile","kind":"Ex","details":"Tarnspawn may spit a stream of acidic bile up to 40 ft. as a ranged attack."}],"before_combat":"If the tarnspawn stalk humans or expect combat, roughly half of the pack hides, attempting to prowl behind their prey or leap unexpectedly from ambush.","during_combat":"Tarnspawn in a group reserve one member each round to unleash a terrifying howl (using their Dazzling Display feat; remember to include a +4 bonus if the tarnspawn are larger than their opponents). They eschew weapons, instead using their claws and fangs and focusing on shaken opponents.","morale":"Tarnspawn fight until destroyed.","base_statistics":"When not raging, a tarnspawn's statistics are AC 20, touch 12, flat-footed 17; hp 99; Fort +8, Will+10; Melee bite +16 (1d8+6/19-20), 2 claws +17 (1d6+6); Str 22, Con 16; CMB 18, CMD 30; Intimidate +21, Swim +14","source":"PFS S2-12, Advanced Bestiary 167, Advanced Player's Guide 79, Pathfinder  RPG Bestiary 119"},{"name":"Carnag","cr":11,"xp":12800,"race":"dark naga","gender":"Male","age_category":"Adult","alignment":"LE","size":"Large","type":"aberration","templates_applied":"advanced","init":6,"senses":["darkvision 60 ft.","detect thoughts"],"ac":24,"ac_touch":16,"ac_flat_footed":17,"ac_mods":"+6 Dex, +1 dodge, +8 natural, -1 size","hp":152,"hd":"16d8+80","hd_value":16,"fort":10,"ref":13,"will":14,"save_mods":"Will: +16 vs. charm effects","defensive_abilities":["guarded thoughts"],"immunities":["poison"],"speed":[{"type":"land","speed":40}],"melee":"bite +13 (1d6+3), sting +13 (2d6+3 plus poison)","space":"10 ft.","reach":"5 ft.","spellsknown_caster_level":10,"spellsknown_concentration":13,"spellsknown":[{"spell_level":5,"spell_slots":3,"spells":[{"spell":"interposing hand"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"greater invisibility"},{"spell":"wall of ice"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"displacement"},{"spell":"lightning bolt"},{"spell":"stinking cloud"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"cat's grace"},{"spell":"invisibility"},{"spell":"scorching ray"},{"spell":"web"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"expeditious retreat"},{"spell":"magic missile"},{"spell":"ray of enfeeblement"},{"spell":"reduce person"},{"spell":"shield"},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"detect magic"},{"spell":"light"},{"spell":"made hand"},{"spell":"mending"},{"spell":"open/ close"},{"spell":"ray of frost"},{"spell":"read magic"},{"spell":"touch of fatigue"}]}],"strength":14,"dexterity":23,"constitution":20,"intelligence":16,"wisdom":15,"charisma":17,"baseatk":12,"cmb":15,"cmd":32,"cmd_special":"can't be tripped","feats":[{"feat":"Alertness"},{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Eschew Materials","type":"bonus"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Stealthy"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Diplomacy","value":11},{"skill":"Disguise","value":9},{"skill":"Escape Artist","value":18},{"skill":"Intimidate","value":16},{"skill":"Knowledge (arcana)","value":19},{"skill":"Knowledge (history)","value":4},{"skill":"Knowledge (religion)","value":4},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":21},{"skill":"Spellcraft","value":18},{"skill":"Stealth","value":23}],"languages":["Common","Hallit","Infernal","Undercommon"],"special_abilities":[{"type":"Detect Thoughts","kind":"Su","details":"Carnag can continuously use detect thoughts as per the spell (caster level 9th; Will DC 18 negates). The save DC is Charisma-based."},{"type":"Guarded Thoughts","kind":"Ex","details":"Carnag is immune to any form of mind reading, such as that granted by detect thoughts. This ability also grants a +2 racial bonus on all saves against charm effects."},{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 23; frequency 1 round; effect sleep for 2d4 minutes; cure 1 save."},{"type":"Spells","details":"Carnag casts spells as a 10th-level sorcerer."}],"before_combat":"Carnag slithers into hiding when he hears anyone descend the stairs, using cat's grace to improve his Stealth, but calls out to learn who is there. If the conversation goes poorly, he casts greater invisibility on himself before moving from his hiding place and uses detect thoughts to identify the cleverest of the group to target with his poisoned sting in the surprise round.","during_combat":"Carnag uses his interposing hand, wall of ice, and web spells to separate a group, isolating single targets to confront. He alternates using his poisoned sting and damaging spells, but prefers to keep mobile and rarely makes full-attack actions, trying to use the deep pits to prevent himself from being flanked or overwhelmed.","morale":"While Carnag would normally flee combat after losing half his normal hit points, his geas forces him to fight to the death. Once reduced below half his normal hit points, he begs for mercy while maintaining the attack.","source":"PFS S2-12, Pathfinder RPG Bestiary 211"},{"name":"Stom Dolock","cr":8,"xp":4800,"race":"dwarf","gender":"Male","age_category":"Adult","classes":[{"class":"oracle","level":10}],"alignment":"LE","size":"Large","type":"humanoid","sub_types":["dwarf"],"init":-2,"senses":["blindsense 30 ft.","darkvision 60 ft."],"ac":19,"ac_touch":7,"ac_flat_footed":19,"ac_mods":"+10 armor, -2 Dex, +2 natural, -1 size","hp":118,"hd":"10d8+70","hd_value":10,"fort":10,"ref":1,"will":9,"save_mods":"+2 vs. poison, spells, and spell-like  abilities","dr":"5/good","speed":[{"type":"land","speed":20}],"melee":"heavy pick +12 (1d8+5/19-20/x4)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"+1 on attack rolls against goblinoid and Orc humanoids"}],"spellsknown_caster":"oracle","spellsknown_caster_level":10,"spellsknown_concentration":12,"spellsknown":[{"spell_level":5,"spell_slots":3,"spells":[{"spell":"flame strike"},{"spell":"righteous might"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"divine power"},{"spell":"inflict critical wounds"},{"spell":"unholy blight"},{"spell":"wall of fire"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"bestow curse"},{"spell":"cure serious wounds"},{"spell":"inflict serious wounds"},{"spell":"invisibility purge"},{"spell":"magic vestment"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"bear's endurance"},{"spell":"bull's strength"},{"spell":"fog cloud"},{"spell":"hold person"},{"spell":"inflict moderate wounds"},{"spell":"instant armor"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"cure light wounds"},{"spell":"divine favor"},{"spell":"enlarge person"},{"spell":"inflict light wounds"},{"spell":"magic weapon"},{"spell":"protection from good"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"guidance"},{"spell":"mending"},{"spell":"resistance"},{"spell":"stabilize"},{"spell":"virtue"}]}],"mystery":"Battle","strength":21,"dexterity":6,"constitution":24,"intelligence":10,"wisdom":14,"charisma":15,"baseatk":7,"cmb":13,"cmd":21,"cmd_special":"25 vs. bull rush, 25 vs. trip","feats":[{"feat":"Cleave"},{"feat":"Combat Casting"},{"feat":"Extra Revelation*"},{"feat":"Improved Critical (heavy pick)"},{"feat":"Power Attack"},{"feat":"Weapon Focus (heavy pick)"}],"skills":[{"skill":"Intimidate","value":14},{"skill":"Knowledge (engineering)","value":12},{"skill":"Knowledge (history)","value":6},{"skill":"Knowledge (planes)","value":8},{"skill":"Knowledge (religion)","value":8},{"skill":"Sense Motive","value":15},{"skill":"Spellcraft","value":12}],"languages":["Common","Dwarven","Infernal"],"sq":["oracle's curse (clouded vision)","possession","revelations (combat healer, skill at arms, war sight)","weapon familiarity"],"special_abilities":[{"type":"Possession","kind":"Su","details":"Nicoroux's fell influence grants Stom incredible powers, but leaves him susceptible to several magical effects. Protection from evil and protection from law affect Stom as if he were an evil creature, and he may not touch any creature benefiting from either spell. Additionally, Nicoroux's control is instantly ended with a successful dispel evil or dispel law spell delivered as a touch attack."},{"type":"Weapon Familiarity","kind":"Ex","details":"By virtue of his years using the tool, Stom may wield his mining pick in combat as a heavy pick without taking an improvised weapon penalty."}],"gear":"miner's pick","before_combat":"Stom has already cast bear's endurance, bull's strength, instant armor, and magic vestment for his earlier fight with the other survivors, and has also taken a small amount of damage, reducing him to 101 hit points. If the PCs are especially loud or noisy returning from the basement, he prepares by casting righteous might on himself. (All of these spells are included in his stats).","during_combat":"Stom uses his war sight revelation to roll initiative twice and take the better result, then casts wall of fire to surround the PCs in a circle of flames. Afterward, he casts sanctuary on himself to finish his combat preparations, casting divine power, and if time permits, magic weapon. He then unleashes unholy blight and flame strike on clustered groups of PCs, swinging with his pick whenever an opponent gets within melee range. If reduced below half his normal hit points, he uses a swift action each round to cast a cure spell using his combat healer revelation.","morale":"If reduced below 20 hit points, Stom collapses as Nicoroux's hold over him slips. He returns to his former neutral alignment and begs for leniency. Only the vaguest memories of the past half-hour remain.","source":"PFS S2-12, Advanced Player's Guide 42"},{"name":"Stom Dolock Tier 10-11","cr":11,"xp":12800,"race":"dwarf","gender":"Male","age_category":"Adult","classes":[{"class":"oracle","level":13}],"alignment":"NE","size":"Large","type":"humanoid","sub_types":["dwarf"],"init":-2,"senses":["blindsense 30 feet","darkvision 60 ft."],"ac":21,"ac_touch":7,"ac_flat_footed":21,"ac_mods":"+12 armor, -2 Dex, +2 natural, -1 size+4 dodge vs. giants","hp":166,"hd":"13d8+104","hd_value":13,"fort":13,"ref":2,"will":10,"save_mods":"+2 vs. poison, spells, and spell-like abilities","dr":"5/good 10/adamantine","speed":[{"type":"land","speed":20}],"melee":"heavy pick +14 (1d8+5/19-20/x4)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"+1 on attack rolls against goblinoid and Orc humanoids"}],"spellsknown_caster":"oracle","spellsknown_caster_level":13,"spellsknown_concentration":16,"spellsknown":[{"spell_level":6,"spell_slots":4,"spells":[{"spell":"animate objects"},{"spell":"blade barrier"},{"spell":"mass bull's strength"}]},{"spell_level":5,"spell_slots":6,"spells":[{"spell":"flame strike"},{"spell":"righteous might"},{"spell":"slay living"},{"spell":"true seeing"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"cure critical wounds"},{"spell":"divine power"},{"spell":"greater magic weapon"},{"spell":"inflict critical wounds"},{"spell":"unholy blight"},{"spell":"wall of fire"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"bestow curse"},{"spell":"cure serious wounds"},{"spell":"inflict serious wounds"},{"spell":"invisibility purge"},{"spell":"magic vestment"},{"spell":"prayer"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"bear's endurance"},{"spell":"bull's strength"},{"spell":"fog cloud"},{"spell":"hold person"},{"spell":"inflict moderate wounds"},{"spell":"instant armor"},{"spell":"make whole"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"cure light wounds"},{"spell":"divine favor"},{"spell":"enlarge person"},{"spell":"inflict light wounds"},{"spell":"magic weapon"},{"spell":"protection from good"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"guidance"},{"spell":"light"},{"spell":"mending"},{"spell":"resistance"},{"spell":"stabilize"},{"spell":"virtue"}]}],"mystery":"Battle","strength":21,"dexterity":6,"constitution":24,"intelligence":10,"wisdom":14,"charisma":16,"baseatk":9,"cmb":15,"cmd":23,"cmd_special":"27 vs. bull rush, 27 vs. trip","feats":[{"feat":"Cleave"},{"feat":"Combat Casting"},{"feat":"Extra Revelation"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (heavy pick)"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (heavy pick)"}],"skills":[{"skill":"Intimidate","value":18},{"skill":"Knowledge (engineering)","value":15},{"skill":"Knowledge (history)","value":8},{"skill":"Knowledge (planes)","value":8},{"skill":"Knowledge (religion)","value":8},{"skill":"Sense Motive","value":18},{"skill":"Spellcraft","value":16}],"languages":["Common","Dwarven","Infernal"],"sq":["oracle's curse (clouded vision)","possession","revelations (combat healer, iron skin, skill at arms, war sight, weapon mastery)","weapon familiarity"],"special_abilities":[{"type":"Possession","kind":"Su","details":"Nicoroux's fell influence grants Stom incredible powers, but leaves him susceptible to several magical effects. Protection from evil and protection from law affect Stom as if he were an evil creature, and he may not touch any creature benefiting from either spell. Additionally, Nicoroux's control is instantly ended with a successful dispel evil or dispel law spell delivered as a touch attack."},{"type":"Weapon Familiarity","kind":"Ex","details":"By virtue of his years using the tool, Stom may wield his mining pick in combat as a heavy pick without taking an improvised weapon penalty."}],"gear":"miner's pick","before_combat":"Stom has already cast bear's endurance, bull's strength, instant armor, and magic vestment for his earlier fight with the other survivors, and has also taken a small amount of damage, reducing him to 153 hit points. If the PCs are especially loud or noisy returning from the basement, he prepares by casting righteous might on himself and activates his iron skin revelation. (All of these spells and the revelation are included in his stats).","during_combat":"Stom uses his war sight revelation to roll initiative three times and take the best result, then casts blade barrier to surround the PCs in a circle of steel. Afterward, he casts animate object to animate three Medium-sized statues of Aroden to harry any remaining PCs, using the free time it buys him to cast divine power. He then unleashes unholy blight and flame strike on clustered groups of PCs. If opponents close to melee, he switches to slay living. If reduced below half his normal hit points, he uses a swift action each round to cast a cure spell using his combat healer revelation.","morale":"If reduced below 20 hit points, Stom collapses as Nicoroux's hold over him slips. He returns to his former neutral alignment and begs for leniency.","source":"PFS S2-12"},{"name":"Silver Tarn Avatar","cr":11,"xp":12800,"race":"greater water elemental","age_category":"Adult","alignment":"LE","size":"Huge","type":"outsider","sub_types":["elemental","native","water"],"templates_applied":"half-fiend","init":6,"senses":["darkvision 60 ft."],"ac":25,"ac_touch":15,"ac_flat_footed":18,"ac_mods":"+6 Dex, +1 dodge, +10 natural, -2 size","hp":149,"hd":"13d10+78","hd_value":13,"fort":14,"ref":14,"will":5,"dr":"10/-","immunities":["elemental traits","poison"],"resists":["acid 10","cold 10","electricity 10","fire 10"],"sr":22,"speed":[{"type":"fly","speed":40,"maneuverability":"good"},{"type":"land","speed":20},{"type":"swim","speed":90}],"melee":"2 slams +22 (1d8+11/19-20)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"drench"},{"type":"smite good","details":"1/day"},{"type":"vortex","details":"DC 27"},{"type":"water mastery"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"blasphemy"},{"spell":"contagion"},{"spell":"desecrate"},{"spell":"unhallow"},{"spell":"unholy blight"}]},{"frequency":"3/day","spells":[{"spell":"darkness"},{"spell":"poison"},{"spell":"unholy aura"}]}],"strength":32,"dexterity":22,"constitution":23,"intelligence":12,"wisdom":13,"charisma":13,"baseatk":13,"cmb":26,"cmd":43,"feats":[{"feat":"Bull Rush Strike*"},{"feat":"Cleave"},{"feat":"Dodge"},{"feat":"Great Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (slams)"},{"feat":"Power Attack"}],"skills":[{"skill":"Acrobatics","value":22,"special":"-4 jump"},{"skill":"Escape Artist","value":22},{"skill":"Fly","value":10},{"skill":"Intimidate","value":14},{"skill":"Knowledge (planes)","value":17},{"skill":"Perception","value":17},{"skill":"Stealth","value":14},{"skill":"Swim","value":35}],"languages":["Aquan","Infernal (cannot speak)"],"before_combat":"The avatar has no interest in subtlety, and attacks swiftly and inelegantly.","during_combat":"The avatar begins combat by casting unholy blight, followed by blasphemy, then focuses on melee combat. Thanks to her Bull Rush Strike feat, she knocks opponents back (and ideally into the water) whenever she confirms a critical hit. When reduced below half her normal hit points, she dives underwater and uses her vortex ability to toss about any opponents in the water or on the lake's surface. If all her opponents are flying, she simply continues her physical assault.","morale":"The Silver Tarn avatar fights until destroyed.","source":"PFS S2-12, Pathfinder RPG Bestiary 127, 171"},{"name":"Silver Tarn Avatar Tier 10-11","cr":14,"xp":38400,"race":"water elemental","age_category":"elder","alignment":"LE","size":"Huge","type":"outsider","sub_types":["elemental","native","water"],"templates_applied":"half-fiend","init":8,"senses":["darkvision 60 ft."],"ac":27,"ac_touch":17,"ac_flat_footed":18,"ac_mods":"+8 Dex, +1 dodge, +10 natural, -2 size","hp":200,"hd":"16d10+112","hd_value":16,"fort":16,"ref":18,"will":6,"dr":"10/-","immunities":["elemental traits","poison"],"resists":["acid 10","cold 10","electricity 10","fire 10"],"sr":25,"speed":[{"type":"fly","speed":40,"maneuverability":"good"},{"type":"land","speed":20},{"type":"swim","speed":90}],"melee":"2 slams +26 (1d8+12/19-20)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"drench"},{"type":"smite good","details":"1/day"},{"type":"vortex","details":"DC 30"},{"type":"water mastery"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"blasphemy"},{"spell":"contagion"},{"spell":"desecrate"},{"spell":"horrid wilting"},{"spell":"unhallow"},{"spell":"unholy blight"}]},{"frequency":"3/day","spells":[{"spell":"darkness"},{"spell":"poison"},{"spell":"unholy aura"}]}],"strength":34,"dexterity":26,"constitution":23,"intelligence":12,"wisdom":13,"charisma":13,"baseatk":16,"cmb":30,"cmd":49,"feats":[{"feat":"Bull Rush Strike*"},{"feat":"Cleave"},{"feat":"Dodge"},{"feat":"Great Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (slams)"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":27,"special":"-4 jump"},{"skill":"Escape Artist","value":27},{"skill":"Fly","value":12},{"skill":"Intimidate","value":17},{"skill":"Knowledge (planes)","value":20},{"skill":"Perception","value":20},{"skill":"Stealth","value":19},{"skill":"Swim","value":39}],"languages":["Aquan","Infernal (cannot speak)"],"before_combat":"Before breaking the water's surface, the avatar casts unholy aura on itself.","during_combat":"The avatar begins combat by casting horrid wilting, followed by blasphemy, then focuses on melee combat. If any PC throws or drops a blessed ingot into the lake, she uses her daily smite good ability, and focuses all attacks on that target. Thanks to her Bull Rush Strike feat, she knocks opponents back (and ideally into the water) whenever she confirms a critical hit. When reduced below half her normal hit points, she dives underwater and uses her vortex ability to toss about any opponents in the water or on the lake's surface. If all her opponents are flying, she simply continues her physical assault.","morale":"The Silver Tarn avatar fights until destroyed.","source":"PFS S2-12, Pathfinder RPG Bestiary 127, 171"},{"name":"Verbovezzor","cr":16,"xp":76800,"race":"Mythic vescavor swarm","age_category":"Adult","alignment":"CE","size":"Diminutive","type":"outsider","sub_types":["chaotic","evil","mythic","swarm"],"init":15,"init_special":"M","senses":["darkvision 60 ft."],"auras":["gibber (15 ft., DC 22)"],"ac":29,"ac_touch":21,"ac_flat_footed":22,"ac_mods":"+5 Dex, +2 dodge, +8 natural, +4 size","hp":238,"hd":"17d10+145","hd_value":17,"fort":16,"ref":17,"will":8,"defensive_abilities":["evasion","rejuvenation","swarm traits"],"dr":"10/epic","immunities":["mind-affecting effects","poison","weapon damage"],"resists":["electricity 10","fire 10"],"sr":33,"speed":[{"type":"fly","speed":40,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"swarm (8d6 plus distraction and 1d4 Charisma drain)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"Charisma drain"},{"type":"distraction"},{"type":"mythic power","details":"6/day, surge +1d8"},{"type":"ravenous"},{"type":"traumatizing"}],"strength":7,"dexterity":20,"constitution":18,"intelligence":10,"wisdom":13,"charisma":12,"baseatk":17,"feats":[{"feat":"Blind-Fight"},{"feat":"Dodge","type":"mythic"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative","type":"mythic"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Mobility","type":"mythic"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":35},{"skill":"Intimidate","value":21},{"skill":"Knowledge (local)","value":17},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":21},{"skill":"Stealth","value":37}],"languages":["Abyssal"],"sq":["dual initiative"],"special_abilities":[{"type":"Charisma Drain","kind":"Su","details":"Verbovezzor drains fragments of personality and memories from those it feeds upon, dealing 1d4 points of Charisma drain whenever it deals swarm damage. A successful DC 22 Fortitude save reduces the Charisma drain to 1 point of Charisma damage. The save DC is Constitution-based."},{"type":"Gibber","kind":"Su","details":"Any creature within 15 ft. of Verbovezzor must succeed at a DC 22 Will save or be confused for 1 round. This is a mind-affecting compulsion insanity effect. A creature that saves successfully cannot be affected by Verbovezzor's gibber again for 24 hours. The save DC is Constitution-based."},{"type":"Ravenous","kind":"Ex","details":"Verbovezzor ignores hardness of less than 20 when it attacks an object. Each round a creature is in the same space as the swarm, Verbovezzor begins devouring one object on the creature. The object takes an amount of damage equal to half its maximum hit points and becomes broken; a broken object damaged in this way is destroyed. An attended magic item gets a DC 15 Reflex save to negate this effect."},{"type":"Rejuvenation","kind":"Su","details":"If even one of the individual vescavors that makes up Verbovezzor survives the swarm's destruction (this is all but guaranteed, as the swarm always keeps a few dozen hidden in the surrounding area), Verbovezzor can rebuild itself through a fit of reproduction over the course of 24 hours. Permanently slaying Verbovezzor requires powerful magic or diligence. A miracle or wish used to ensure its death after its defeat could certainly do the trick."},{"type":"Traumatizing","kind":"Su","details":"Any creature that spends more than 3 rounds within the swarm must succeed at a DC 19 Will save or become afflicted with a random insanity (GameMastery Guide 250). The save DC is Charisma-based."}],"during_combat":"Verbovezzor moves to engulf as many foes as it can each round, but it particularly enjoys devouring animal companions, familiars, and other \"tidbits,\" since emotional connections of these creatures to the masters serve as lovely appetizers.","morale":"If reduced to fewer than 50 hit points, Verbovezzor attempts to surrender, promising to reveal many important secrets to the PCs in reward for its life.","source":"AP 77, Pathfinder RPG Mythic Adventures 226"},{"name":"Father Of Worms","cr":20,"xp":307200,"race":"Mythic nightcrawler","age_category":"Adult","alignment":"CE","size":"Gargantuan","type":"undead","sub_types":["extraplanar","mythic","nightshade"],"init":8,"init_special":"M","senses":["darksense","darkvision 120 ft.","detect magic","low-light vision","tremorsense 120 ft."],"auras":["desecrating aura (30 ft.)"],"ac":37,"ac_touch":6,"ac_flat_footed":37,"ac_mods":"+31 natural, -4 size","hp":419,"hd":"25d8+307","hd_value":25,"fort":19,"ref":10,"will":23,"defensive_abilities":["corrosive blood"],"dr":"15/good and silver,  10/epic","immunities":["acid","cold","undead traits"],"sr":31,"weaknesses":["light aversion"],"speed":[{"type":"burrow","speed":60},{"type":"land","speed":30}],"melee":"bite +32 (4d10+18/19-20/x3 plus 4d6 cold and grab), sting +32 (4d6+18/19-20 plus 4d6 cold and poison)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"breath weapon"},{"type":"channel negative energy","details":"9d6, DC 37, 9/day"},{"type":"energy drain","details":"1d4 levels, DC 31"},{"type":"fast swallow"},{"type":"mythic power","details":"4/day, surge +1d8"},{"type":"swallow whole","details":"4d10+18 bludgeoning plus 4d10 cold and energy drain, AC 25, 41 hp"}],"spell_like_abilities_caster_level":18,"spell_like_abilities_concentration":27,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"detect magic"},{"spell":"magic fang"}]},{"frequency":"at-will","spells":[{"spell":"contagion"},{"spell":"deeper darkness"},{"spell":"greater dispel magic"},{"spell":"invisibility"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"finger of death"},{"spell":"mass hold monster"},{"spell":"plane shift"},{"spell":"summon","details":"6 greater shadows 100%, level 8"}]},{"frequency":"3/day","spells":[{"spell":"confusion"},{"spell":"haste"},{"spell":"hold monster"},{"spell":"quickened cone of cold"}]}],"strength":41,"dexterity":10,"intelligence":20,"wisdom":21,"charisma":29,"baseatk":18,"cmb":37,"cmd":47,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Expertise"},{"feat":"Command Undead"},{"feat":"Critical Focus"},{"feat":"Greater Vital Strike"},{"feat":"Improved Critical (sting)"},{"feat":"Improved CriticalM (bite)"},{"feat":"Improved Initiative","type":"mythic"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (cone of cold)"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Intimidate","value":37},{"skill":"Knowledge (arcana)","value":33},{"skill":"Knowledge (dungeoneering)","value":30},{"skill":"Knowledge (planes)","value":30},{"skill":"Knowledge (religion)","value":33},{"skill":"Perception","value":33},{"skill":"Sense Motive","value":33},{"skill":"Spellcraft","value":33},{"skill":"Stealth","value":16,"special":"+8 in dim light and darkness"}],"languages":["Common","Abyssal","Infernal","telepathy 100 ft."],"special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"Once every 1d4 rounds as a move action, the Father of Worms can breathe a 90-foot cone of black energy. This deals 20d6 points of cold damage and imparts 1d4 negative levels to all creatures in that area. A successful DC 31 Reflex save halves the cold damage and negates the negative levels. The save DC is Charisma-based."},{"type":"Corrosive Blood","kind":"Su","details":"A creature that strikes the Father of Worms with a slashing or piercing melee attack must succeed at a DC 31 Reflex save or take 2d6 points of acid damage. This damage affects the weapon used to damage the monster as well-the damage isn't halved against objects and ignores hardness. The acidic blood swiftly becomes inert unless captured in a vessel capable of storing it, in which case it retains its corrosive properties until poured out."}],"during_combat":"The Father of Worms starts a fight by summoning its six greater shadows, using quickened cones  of cold on the first 3 rounds of combat to supplement its other ranged magical attacks. It casts haste on itself and any surviving shadows before entering melee.","morale":"The Father of Worms fights to the death.","source":"AP 77, Pathfinder RPG Bestiary 2 200, Pathfinder RPG Mythic Adventures 226"},{"name":"Half-Fiend Great Cyclops","cr":15,"xp":51200,"race":"great cyclops","age_category":"Adult","alignment":"CE","size":"Huge","type":"outsider","sub_types":["native"],"templates_applied":"half-fiend","init":2,"senses":["darkvision 60 ft.","low-light vision"],"ac":32,"ac_touch":10,"ac_flat_footed":30,"ac_mods":"+8 armor, +2 Dex, +14 natural, -2 size","hp":229,"hd":"17d8+153","hd_value":17,"fort":14,"ref":7,"will":15,"dr":"10/magic","immunities":["poison"],"resists":["acid 10","cold 10","electricity 10","fire 10"],"sr":26,"speed":[{"type":"fly","speed":100,"maneuverability":"good"},{"type":"land","speed":35}],"melee":"+1 wounding glaive +26 (3d8+22/19-20/x3), bite +19 (2d6+7), gore +19 (1d8+7)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"powerful charge","details":"gore, 4d8+22"},{"type":"rock throwing","details":"120 ft."},{"type":"smite good","details":"1/day"}],"spell_like_abilities_caster_level":17,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"blasphemy"},{"spell":"contagion"},{"spell":"desecrate"},{"spell":"horrid wilting"},{"spell":"summon monster IX","details":"fiends only"},{"spell":"unhallow"},{"spell":"unholy blight"}]},{"frequency":"3/day","spells":[{"spell":"darkness"},{"spell":"poison"},{"spell":"unholy aura"}]}],"strength":38,"dexterity":15,"constitution":29,"intelligence":11,"wisdom":16,"charisma":12,"baseatk":12,"cmb":28,"cmb_special":"+32 bull rush","cmd":40,"cmd_special":"42 vs. bull rush","feats":[{"feat":"Awesome Blow"},{"feat":"Combat Reflexes"},{"feat":"Greater Bull Rush"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (glaive)"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (glaive)"}],"skills":[{"skill":"Acrobatics","value":16},{"skill":"Fly","value":19},{"skill":"Intimidate","value":18},{"skill":"Perception","value":26},{"skill":"Sense Motive","value":20},{"skill":"Stealth","value":8}],"languages":["Common","Cyclops","Giant"],"sq":["flash of brutality"],"gear":"+2 breastplate, +1 wounding glaive","during_combat":"The half-fiend great cyclopes prefer to fight in melee, and are capable of inflicting punishing blows since they prefer to attack with the aid of Power Attack. They use their spells against those who try to fight at range, but aren't afraid to take to the air to attack as well since the prison's spines won't fire on them.","morale":"Ever loyal, the two half-fiend great cyclopes fight to the death.","source":"AP 77, Pathfinder RPG Bestiary 171, Pathfinder RPG Bestiary 2 61"},{"name":"Pool Of Ultimate Ending","cr":15,"xp":51200,"race":"Colossal mythic crystal ooze","age_category":"Adult","alignment":"N","size":"Colossal","type":"ooze","sub_types":["aquatic","mythic"],"init":0,"senses":["blindsight 60 ft."],"auras":["unholy aura (DC 13)"],"ac":26,"ac_touch":6,"ac_flat_footed":26,"ac_mods":"+4 deflection, +20 natural, -8 size","hp":376,"hd":"16d8+304","hd_value":16,"hp_mods":"regeneration 15 (good spell or weapon)","fort":25,"ref":9,"will":4,"dr":"10/epic","immunities":["acid","cold","fire","ooze traits"],"sr":26,"speed":[{"type":"land","speed":10},{"type":"swim","speed":30}],"melee":"2 slams +23 (4d8+28 plus paralysis)","space":"30 ft.","reach":"60 ft.","special_attacks":[{"type":"acid"},{"type":"mythic power","details":"6/day, surge +1d8"},{"type":"potent paralysis"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"unholy aura"}]}],"strength":48,"dexterity":10,"constitution":42,"wisdom":1,"charisma":1,"baseatk":12,"cmb":39,"cmd":53,"skills":[{"skill":"Swim","value":27}],"special_abilities":[{"type":"Potent Paralysis","kind":"Ex","details":"A creature damaged by the ooze's slam attack must also succeed at a DC 34 Fortitude save or be paralyzed for 3d6 rounds. This paralysis effect can even affect those under the protection of freedom of movement, or who are normally immune to paralysis effects, although mythic creatures who have immunity to paralysis gain a +10 bonus on their saving throws to resist. When used to paralyze a creature normally immune to the effect, this is a supernatural ability. The save DC is Constitution-based."}],"during_combat":"The ooze, despite being unintelligent, can sense the difference between chaotic evil outsiders and other creatures. It doesn't attack chaotic evil outsiders, but furiously assaults all other intruders into this chamber with its immense acidic pseudopods as long as they remain within 60 ft. of the acid surface below.","morale":"The vast ooze fights to the death.","source":"AP 77, Pathfinder RPG Bestiary 166, Pathfinder RPG Mythic Adventures 226"}];
